import { CommonModule } from "@angular/common";
import { HttpClientModule } from "@angular/common/http";
import { NgModule } from "@angular/core";
import { ReactiveFormsModule } from "@angular/forms";
import { RouterModule } from "@angular/router";

import {
    NuiButtonModule,
    NuiDocsModule,
    NuiFormFieldModule,
    NuiIconModule,
    NuiMessageModule,
    NuiSwitchModule,
    NuiTextboxModule,
    DEMO_PATH_TOKEN,
} from "@nova-ui/bits";
import {
    NuiDashboardConfiguratorModule,
    NuiDashboardsModule,
} from "@nova-ui/dashboards";

import {
    CustomConfiguratorSectionExampleComponent,
    CustomKpiDescriptionConfigurationComponent,
} from "./custom-configurator-section/custom-configurator-section.example.component";
import { CustomConfiguratorSectionDocsComponent } from "./custom-configurator-section-docs.component";
import { getDemoFiles } from "../../../../../demo-files-factory";

const routes = [
    {
        path: "",
        component: CustomConfiguratorSectionDocsComponent,
        data: {
            srlc: {
                hideIndicator: true,
            },
            showThemeSwitcher: true,
        },
    },
    {
        path: "example",
        component: CustomConfiguratorSectionExampleComponent,
        data: {
            srlc: {
                hideIndicator: true,
            },
        },
    },
];

@NgModule({
    imports: [
        CommonModule,
        ReactiveFormsModule,
        HttpClientModule,
        NuiDashboardsModule,
        NuiDashboardConfiguratorModule,
        NuiDocsModule,
        NuiFormFieldModule,
        NuiIconModule,
        NuiMessageModule,
        NuiSwitchModule,
        NuiTextboxModule,
        NuiButtonModule,
        RouterModule.forChild(routes),
    ],
    declarations: [
        CustomConfiguratorSectionDocsComponent,
        CustomKpiDescriptionConfigurationComponent,
        CustomConfiguratorSectionExampleComponent,
    ],
    providers: [
        {
            provide: DEMO_PATH_TOKEN,
            useValue: getDemoFiles("configurator-section"),
        },
    ],
})
export default class CustomConfiguratorSectionModule {}
