import { CommonModule } from "@angular/common";
import { HttpClientModule } from "@angular/common/http";
import { NgModule } from "@angular/core";
import { RouterModule } from "@angular/router";

import {
    NuiButtonModule,
    NuiDocsModule,
    NuiMessageModule,
    NuiSwitchModule,
    DEMO_PATH_TOKEN,
} from "@nova-ui/bits";
import { NuiDashboardsModule } from "@nova-ui/dashboards";

import { WidgetEditorDocsComponent } from "./widget-editor-setup-docs.component";
import { WidgetEditorSetupComponent } from "./widget-editor-setup.component";
import { getDemoFiles } from "../../../../demo-files-factory";

const routes = [
    {
        path: "",
        component: WidgetEditorDocsComponent,
        data: {
            srlc: {
                hideIndicator: true,
            },
            showThemeSwitcher: true,
        },
    },
    {
        path: "example",
        component: WidgetEditorSetupComponent,
        data: {
            srlc: {
                hideIndicator: true,
            },
        },
    },
];

@NgModule({
    imports: [
        CommonModule,
        HttpClientModule,
        NuiDashboardsModule,
        NuiDocsModule,
        NuiMessageModule,
        NuiSwitchModule,
        NuiButtonModule,
        RouterModule.forChild(routes),
    ],
    declarations: [WidgetEditorDocsComponent, WidgetEditorSetupComponent],
    providers: [
        {
            provide: DEMO_PATH_TOKEN,
            useValue: getDemoFiles("widget-editor-setup"),
        },
    ],
})
export default class WidgetEditorSetupModule {}
