import { NuiDashboardsModule } from "@nova-ui/dashboards";

import { DrilldownMultiRequestWidgetExampleComponent } from "./drilldown-multi-request-widget/drilldown-multi-request-widget-example.component";
import { DrilldownWidgetExampleComponent } from "./drilldown-widget/drilldown-widget-example.component";
import { DrilldownDocsComponent } from "./drilldown-widget-docs.component";
import { getDemoFiles } from "../../../../demo-files-factory";

const routes: Routes = [
    {
        path: "",
        component: DrilldownDocsComponent,
        data: {
            srlc: {
                hideIndicator: true,
            },
        },
    },
    {
        path: "example",
        component: DrilldownWidgetExampleComponent,
        data: {
            srlc: {
                hideIndicator: true,
            },
        },
    },
    {
        path: "multiple-requests",
        component: DrilldownMultiRequestWidgetExampleComponent,
        data: {
            srlc: {
                hideIndicator: true,
            },
        },
    },
];

@NgModule({
    imports: [
        RouterModule.forChild(routes),
        NuiButtonModule,
        NuiDocsModule,
        NuiMessageModule,
        NuiDashboardsModule,
        NuiSwitchModule,
    ],
    declarations: [
        DrilldownDocsComponent,
        DrilldownWidgetExampleComponent,
        DrilldownMultiRequestWidgetExampleComponent,
    ],
    providers: [
        {
            provide: DEMO_PATH_TOKEN,
            useValue: getDemoFiles("drilldown"),
        },
    ],
})
export default class DrilldownDocsModule {}
