import { NgModule } from "@angular/core";
import { RouterModule, Routes } from "@angular/router";

import {
    NuiButtonModule,
    NuiDocsModule,
    NuiMessageModule,
    NuiSwitchModule,
    DEMO_PATH_TOKEN,
} from "@nova-ui/bits";
import { NuiDashboardsModule } from "@nova-ui/dashboards";

import { ProportionalDocsComponent } from "./proportional-docs.component";
import { ProportionalDonutContentDocsComponent } from "./proportional-donut-content-docs.component";
import { ProportionalWidgetDonutContentFormattersExampleComponent } from "./proportional-donut-content-formatters/proportional-donut-content-formatters-example.component";
import { ProportionalWidgetExampleComponent } from "./proportional-widget/proportional-widget-example.component";
import { ProportionalWidgetInteractiveExampleComponent } from "./proportional-widget-interactive/proportional-widget-interactive-example.component";
import { getDemoFiles } from "../../../../demo-files-factory";

const routes: Routes = [
    {
        path: "",
        component: ProportionalDocsComponent,
        data: {
            srlc: {
                hideIndicator: true,
            },
            showThemeSwitcher: true,
        },
    },
    {
        path: "example",
        component: ProportionalWidgetExampleComponent,
        data: {
            srlc: {
                hideIndicator: true,
            },
        },
    },
    {
        path: "donut-content-formatters",
        component: ProportionalDonutContentDocsComponent,
        data: {
            srlc: {
                hideIndicator: true,
            },
        },
    },
    {
        path: "donut-content-formatters-example",
        component: ProportionalWidgetDonutContentFormattersExampleComponent,
        data: {
            srlc: {
                hideIndicator: true,
            },
        },
    },
    {
        path: "proportional-widget-interactive-example",
        component: ProportionalWidgetInteractiveExampleComponent,
        data: {
            srlc: {
                hideIndicator: true,
            },
        },
    },
];

@NgModule({
    imports: [
        RouterModule.forChild(routes),
        NuiButtonModule,
        NuiDocsModule,
        NuiDashboardsModule,
        NuiMessageModule,
        NuiSwitchModule,
    ],
    declarations: [
        ProportionalDocsComponent,
        ProportionalWidgetExampleComponent,
        ProportionalWidgetInteractiveExampleComponent,
        ProportionalWidgetDonutContentFormattersExampleComponent,
        ProportionalDonutContentDocsComponent,
    ],
    providers: [
        {
            provide: DEMO_PATH_TOKEN,
            useValue: getDemoFiles("proportional"),
        },
    ],
})
export default class ProportionalDocsModule {}
