import { NgModule } from "@angular/core";
import { RouterModule, Routes } from "@angular/router";

import {
    DEMO_PATH_TOKEN,
    NuiButtonModule,
    NuiDocsModule,
    NuiMessageModule,
    NuiSwitchModule,
} from "@nova-ui/bits";
import { NuiDashboardsModule } from "@nova-ui/dashboards";

import { RiskScoreDocsComponent } from "./risk-score-docs.component";
import { RiskScoreWidgetExampleComponent } from "./risk-score-widget-example/risk-score-widget-example.component";
import { getDemoFiles } from "../../../../demo-files-factory";

const routes: Routes = [
    {
        path: "",
        component: RiskScoreDocsComponent,
        data: {
            srlc: {
                hideIndicator: true,
            },
            showThemeSwitcher: true,
        },
    },
    {
        path: "example",
        component: RiskScoreWidgetExampleComponent,
        data: {
            srlc: {
                hideIndicator: true,
            },
        },
    },
];

@NgModule({
    imports: [
        RouterModule.forChild(routes),
        NuiButtonModule,
        NuiDocsModule,
        NuiMessageModule,
        NuiDashboardsModule,
        NuiSwitchModule,
    ],
    declarations: [RiskScoreDocsComponent, RiskScoreWidgetExampleComponent],
    providers: [
        {
            provide: DEMO_PATH_TOKEN,
            useValue: getDemoFiles("risk-score"),
        },
    ],
})
export default class RiskScoreDocsModule {}
